现在为刚才的 LRU 缓存加上线程安全锁 (threading.Lock)，并编写一个基准性能测试函数，输出多线程并发测试结果表格。
Sep 2, 2026, 12:08:31 PM PDT
 在多线程并发场景下，访问与修改 LRU 缓存需要保证原子性。由于  get  操作会改变双向链表中的节点顺序（移动节点到头部），因此   get  和  put  操作均属于写操作 ，都需要通过互斥锁保护。 



 1. 线程安全的 LRU 缓存实现 
 这里使用  threading.Lock  作为上下文管理器（ with self.lock: ）来保证线程安全性。 
  import random
import threading
import time


class Node:
    &quot;&quot;&quot;双向链表节点&quot;&quot;&quot;

    def __init__(self, key: int = 0, value: int = 0):
        self.key = key
        self.value = value
        self.prev = None
        self.next = None


class ThreadSafeLRUCache:
    &quot;&quot;&quot;线程安全的 LRU 缓存实现&quot;&quot;&quot;

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # key -&gt; Node
        self.lock = threading.Lock()  # 互斥锁

        # 初始化伪头节点和伪尾节点
        self.head = Node()
        self.tail = Node()
        self.head.next = self.tail
        self.tail.prev = self.head

    def _add_node_to_head(self, node: Node) -&gt; None:
        &quot;&quot;&quot;内部方法：插入节点到头部（必须在锁保护下调用）&quot;&quot;&quot;
        node.prev = self.head
        node.next = self.head.next
        self.head.next.prev = node
        self.head.next = node

    def _remove_node(self, node: Node) -&gt; None:
        &quot;&quot;&quot;内部方法：从链表移除节点（必须在锁保护下调用）&quot;&quot;&quot;
        prev_node = node.prev
        next_node = node.next
        prev_node.next = next_node
        next_node.prev = prev_node

    def _move_to_head(self, node: Node) -&gt; None:
        &quot;&quot;&quot;内部方法：移动节点到头部（必须在锁保护下调用）&quot;&quot;&quot;
        self._remove_node(node)
        self._add_node_to_head(node)

    def _pop_tail(self) -&gt; Node:
        &quot;&quot;&quot;内部方法：弹出尾部最久未使用的节点（必须在锁保护下调用）&quot;&quot;&quot;
        res_node = self.tail.prev
        self._remove_node(res_node)
        return res_node

    def get(self, key: int) -&gt; int:
        &quot;&quot;&quot;线程安全的 get 操作&quot;&quot;&quot;
        with self.lock:
            if key not in self.cache:
                return -1

            node = self.cache[key]
            self._move_to_head(node)
            return node.value

    def put(self, key: int, value: int) -&gt; None:
        &quot;&quot;&quot;线程安全的 put 操作&quot;&quot;&quot;
        with self.lock:
            if key in self.cache:
                node = self.cache[key]
                node.value = value
                self._move_to_head(node)
            else:
                new_node = Node(key, value)
                self.cache[key] = new_node
                self._add_node_to_head(new_node)

                if len(self.cache) &gt; self.capacity:
                    tail_node = self._pop_tail()
                    del self.cache[tail_node.key]


 2. 多线程并发基准性能测试代码 
 下面定义基准测试函数  benchmark_lru_cache ，它将在多线程并发读写的场景下度量吞吐量（QPS）与平均耗时，并直接输出格式化的 markdown 表格。 
  def benchmark_lru_cache():
    # 测试配置
    thread_counts = [1, 2, 4, 8, 16]
    operations_per_thread = 100_000
    cache_capacity = 1_000
    key_range = 2_000  # 保证一定的 hit / miss 和淘汰触发率

    print(&quot;\n运行并发性能测试中，请稍候...\n&quot;)

    # 格式化输出表格表头
    print(
        f&quot;| 线程数 (Threads) | 总操作数 (Operations) | 总耗时 (Seconds) | 吞吐量 (QPS) | 每万次操作耗时 (ms) |&quot;
    )
    print(
        f&quot;| :--- | :--- | :--- | :--- | :--- |&quot;
    )

    for threads_num in thread_counts:
        cache = ThreadSafeLRUCache(capacity=cache_capacity)
        total_ops = threads_num * operations_per_thread

        def worker():
            # 80% 读取，20% 写入混杂并发
            for _ in range(operations_per_thread):
                key = random.randint(1, key_range)
                if random.random() &lt; 0.8:
                    cache.get(key)
                else:
                    cache.put(key, key)

        threads = []
        for _ in range(threads_num):
            t = threading.Thread(target=worker)
            threads.append(t)

        start_time = time.perf_counter()

        for t in threads:
            t.start()
        for t in threads:
            t.join()

        end_time = time.perf_counter()

        elapsed_time = end_time - start_time
        qps = total_ops / elapsed_time
        time_per_10k_ms = (elapsed_time / total_ops) * 10_000 * 1000

        print(
            f&quot;| {threads_num:&lt;16} | {total_ops:&lt;21,} | {elapsed_time:&lt;16.4f} | {qps:&lt;12,.2f} | {time_per_10k_ms:&lt;19.2f} |&quot;
        )


if __name__ == &quot;__main__&quot;:
    benchmark_lru_cache()


