  class Node:
    &quot;&quot;&quot;双向链表节点&quot;&quot;&quot;

    def __init__(self, key: int = 0, value: int = 0):
        self.key = key
        self.value = value
        self.prev = None
        self.next = None


class LRUCache:
    &quot;&quot;&quot;基于双向链表和哈希表实现的高性能 LRU 缓存&quot;&quot;&quot;

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # 哈希表：key -&gt; Node

        # 初始化伪头节点和伪尾节点，避免复杂的边界判断
        self.head = Node()
        self.tail = Node()
        self.head.next = self.tail
        self.tail.prev = self.head

    def _add_node_to_head(self, node: Node) -&gt; None:
        &quot;&quot;&quot;将节点插入到链表头部（表示最近使用）&quot;&quot;&quot;
        node.prev = self.head
        node.next = self.head.next
        self.head.next.prev = node
        self.head.next = node

    def _remove_node(self, node: Node) -&gt; None:
        &quot;&quot;&quot;从链表中删除指定节点&quot;&quot;&quot;
        prev_node = node.prev
        next_node = node.next
        prev_node.next = next_node
        next_node.prev = prev_node

    def _move_to_head(self, node: Node) -&gt; None:
        &quot;&quot;&quot;将已有节点移动到链表头部&quot;&quot;&quot;
        self._remove_node(node)
        self._add_node_to_head(node)

    def _pop_tail(self) -&gt; Node:
        &quot;&quot;&quot;移除并返回链表尾部的节点（最久未使用）&quot;&quot;&quot;
        res_node = self.tail.prev
        self._remove_node(res_node)
        return res_node

    def get(self, key: int) -&gt; int:
        &quot;&quot;&quot;获取 key 的值；若 key 不存在则返回 -1&quot;&quot;&quot;
        if key not in self.cache:
            return -1

        node = self.cache[key]
        self._move_to_head(node)  # 被访问后更新为最近使用
        return node.value

    def put(self, key: int, value: int) -&gt; None:
        &quot;&quot;&quot;存入 key-value；若 key 存在则更新，超限时淘汰最久未使用的数据&quot;&quot;&quot;
        if key in self.cache:
            node = self.cache[key]
            node.value = value  # 更新值
            self._move_to_head(node)  # 更新为最近使用
        else:
            new_node = Node(key, value)
            self.cache[key] = new_node
            self._add_node_to_head(new_node)

            # 超过容量限制，淘汰最久未使用的元素（尾节点前一个）
            if len(self.cache) &gt; self.capacity:
                tail_node = self._pop_tail()
                del self.cache[tail_node.key]

 设计要点与性能保证 

  伪头尾节点 (Dummy Head/Tail) ：在双向链表两端加入哨兵节点，消除在头部插入或尾部删除时所需的边界判空条件，提升运行效率。 
  双向连接 ：节点同时保留  prev  与  next  指针，使得任意节点在已知指针的前提下均可在 $O(1)$ 时间内被删除。 
  高效查找与存取 ： cache  散列表存储  key -&gt; Node  的映射关系，配合双向链表的结构，确保  get  和  put  操作的时间复杂度均为  $O(1)$ ，空间复杂度为  $O(C)$ （$C$ 为设定的缓存容量）。
